/**
* Safely evaluates a math expression with named variables
*/
function evaluateCustomFormula(formula, variables) {
	try {
		const allowedNames = Object.keys(variables);
		const argNames = allowedNames;
		const argValues = allowedNames.map((k) => variables[k]);
		if (/[;{}[\]`'"\\]/.test(formula) || formula.includes("window") || formula.includes("document") || formula.includes("eval") || formula.includes("Function") || formula.includes("fetch")) return {
			success: false,
			result: 0,
			error: "Illegal character or keyword in formula"
		};
		const sanitizedFormula = formula.replace(/\bsqrt\(/gi, "Math.sqrt(").replace(/\bpow\(/gi, "Math.pow(").replace(/\bPI\b/gi, "Math.PI").replace(/\babs\(/gi, "Math.abs(").replace(/\bround\(/gi, "Math.round(").replace(/\bceil\(/gi, "Math.ceil(").replace(/\bfloor\(/gi, "Math.floor(");
		const val = new Function(...argNames, `return (${sanitizedFormula});`)(...argValues);
		if (typeof val !== "number" || isNaN(val) || !isFinite(val)) return {
			success: false,
			result: 0,
			error: "Math error: result is NaN or infinite"
		};
		return {
			success: true,
			result: val
		};
	} catch (err) {
		return {
			success: false,
			result: 0,
			error: err?.message || "Formula evaluation failed"
		};
	}
}
