function calculateHeronArea(a, b, c) {
	if (a <= 0 || b <= 0 || c <= 0) return {
		area: 0,
		valid: false
	};
	if (a + b <= c || a + c <= b || b + c <= a) return {
		area: 0,
		valid: false
	};
	const s = (a + b + c) / 2;
	return {
		area: Math.sqrt(Math.max(0, s * (s - a) * (s - b) * (s - c))),
		valid: true
	};
}
