	const handleInsertImageFromFile = (chapterIndex, file) => {
		if (!file) return;
		const reader = new FileReader();
		reader.onload = (e) => {
			const rawData = e.target?.result;
			if (!rawData) return;
			const img = new Image();
			img.onload = () => {
				const canvas = document.createElement("canvas");
				const MAX_SIZE = 900;
				let w = img.width;
				let h = img.height;
				if (w > MAX_SIZE || h > MAX_SIZE) {
					if (w > h) {
						h = Math.round(h * MAX_SIZE / w);
						w = MAX_SIZE;
					} else {
						w = Math.round(w * MAX_SIZE / h);
						h = MAX_SIZE;
					}
				}
				canvas.width = w;
				canvas.height = h;
				const ctx = canvas.getContext("2d");
				if (ctx) {
					ctx.drawImage(img, 0, 0, w, h);
					const compressed = canvas.toDataURL("image/jpeg", .82);
					const markdownImg = `\n\n![${prompt("ছবির ক্যাপশন বা শিরোনাম দিন (যেমন: ওয়্যারিং সার্কিট চিত্র):", "সার্কিট ডায়াগ্রাম") || "চিত্র"}](${compressed})\n\n`;
					const updated = [...bChapters];
					updated[chapterIndex].content = (updated[chapterIndex].content || "") + markdownImg;
					setBChapters(updated);
				}
			};
			img.src = rawData;
		};
		reader.readAsDataURL(file);
	};
